-- 签到表（如果还没创建）
DROP TABLE IF EXISTS user_sign;
CREATE TABLE user_sign (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_info_id INT NOT NULL,
  sign_date TIMESTAMP NOT NULL,
  points INT DEFAULT 5,
  continuous_days INT DEFAULT 1
);
-- 帖子点赞表
DROP TABLE IF EXISTS thread_like;
CREATE TABLE thread_like (
  id INT AUTO_INCREMENT PRIMARY KEY,
  thread_info_id INT NOT NULL,
  user_info_id INT NOT NULL,
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_thread_user UNIQUE (thread_info_id, user_info_id)
);
-- 评论点赞表
DROP TABLE IF EXISTS comment_like;
CREATE TABLE comment_like (
  id INT AUTO_INCREMENT PRIMARY KEY,
  comment_id INT NOT NULL,
  user_info_id INT NOT NULL,
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_comment_user UNIQUE (comment_id, user_info_id)
);
-- 用户关注表
DROP TABLE IF EXISTS user_follow;
CREATE TABLE user_follow (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  follow_user_id INT NOT NULL,
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_user_follow UNIQUE (user_id, follow_user_id)
);
-- 用户消息通知表
DROP TABLE IF EXISTS user_message;
CREATE TABLE user_message (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  from_user_id INT,
  TYPE VARCHAR(50) ,
  related_id INT,
  content VARCHAR(500),
  is_read TINYINT DEFAULT 0,
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS user_daily_exp;
CREATE TABLE user_daily_exp (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_info_id INT NOT NULL,
  exp_date DATE NOT NULL,
  exp_got INT DEFAULT 0,
  CONSTRAINT uk_user_date UNIQUE (user_info_id, exp_date)
);

ALTER TABLE user_info ADD COLUMN experience INT DEFAULT 0;
ALTER TABLE user_info ADD COLUMN level INT DEFAULT 1;
ALTER TABLE user_info ADD COLUMN points INT DEFAULT 0;
ALTER TABLE user_info ADD COLUMN thread_count INT DEFAULT 0;
ALTER TABLE user_info ADD COLUMN comment_count INT DEFAULT 0;
ALTER TABLE user_info ADD COLUMN login_count INT DEFAULT 0;
ALTER TABLE user_info ADD COLUMN continuous_login_days INT DEFAULT 0  ;;

-- 成就徽章系统数据库脚本


-- 徽章类型定义表
DROP TABLE IF EXISTS badge_type;
CREATE TABLE badge_type (
  id INT AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(50) NOT NULL UNIQUE ,
  name VARCHAR(50) NOT NULL ,
  description VARCHAR(200) ,
  icon VARCHAR(255) ,
  category VARCHAR(50) ,
  condition_type VARCHAR(50) ,
  condition_value INT NOT NULL ,
  points_reward INT DEFAULT 0 ,
  exp_reward INT DEFAULT 0 ,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 用户徽章关联表
DROP TABLE IF EXISTS user_badge;
CREATE TABLE user_badge (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_info_id INT NOT NULL,
  badge_type_id INT NOT NULL,
  earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  is_show TINYINT DEFAULT 1 ,
  CONSTRAINT uk_user_badge UNIQUE (user_info_id, badge_type_id)
);

