INSERT INTO `thread_info` VALUES
(1, 1, '新生指南', 1, 'Admin', 'newbie_guide.jpg', '新生指南.txt', '面向2022级新生的全方位入学指南，包括选课、宿舍安排、校园环境介绍等，帮助新生快速适应大学生活。', '0', 0),
(2, 2, '考研经验分享', 2, '考研学长', 'kaoyan_exp.jpg', '考研经验.txt', '分享高分学长学姐的考研备考策略、复习方法、心态调整等经验，助力考研顺利上岸。', '1', 0),
(3, 3, '校内兼职信息', 3, '兼职小助手', 'part_time.jpg', NULL, '发布和汇总最新的校内兼职招聘信息，包括家教、商超促销、快递分拣等岗位，为同学们提供灵活的工作机会。', '1', 0),
(4, 16, '程序设计大赛交流', 4, 'ACMer', 'coding_contest.jpg', '程序设计大赛.txt', '分享ACM、蓝桥杯、华为软件精英挑战赛等编程竞赛的经验、解题思路、备赛资源，助力编程竞赛选手提升水平。', '0', 0),
(5, 4, '社团招新', 5, '社团负责人', 'club_recruit.jpg', '社团招新.txt', '汇总各大学生社团的招新信息，帮助新生和在校生找到适合自己的兴趣社团，丰富校园生活。', '0', 0),
(6, 13, '四六级备考资料', 6, '四六级学长', 'cet_guide.jpg', '四六级.txt', '整理英语四六级考试的高分备考资料，包括听力、阅读、写作、翻译攻略及高频词汇总结。', '0', 0),
(7, 49, '校园美食推荐', 7, '吃货小分队', 'campus_food.jpg', NULL, '分享校园及周边美食店铺推荐，涵盖实惠又美味的食堂、外卖、餐馆，让你吃得更好。', '0', 0),
(8, 22, '二手交易', 8, '二手市场', 'second_hand.jpg', NULL, '提供校园二手交易平台，发布和查看二手书籍、电子产品、生活用品等交易信息，促进资源循环利用。', '0', 0),
(9, 21, '失物招领', 9, '热心同学', 'lost_found.jpg', NULL, '发布校园内丢失物品的信息，帮助同学们快速找回遗失的物品，促进校园互助氛围。', '0', 0),
(10, 46, '学术讲座预告', 10, '学术部', 'academic_lecture.jpg', NULL, '汇总近期校内外学术讲座、公开课、论坛沙龙等活动信息，提供学术前沿动态。', '0', 0),
(11, 2, '竞赛信息分享', 11, '竞赛达人', 'competition_info.jpg', NULL, '介绍各类学科竞赛，包括数学建模、人工智能竞赛、黑客马拉松、挑战杯等赛事信息。', '0', 0),
(12, 42, '软件工程就业方向', 12, '程序猿', 'job_trend.jpg', '就业方向.txt', '探讨软件工程专业的就业方向，包括前端、后端、AI、大数据、嵌入式等岗位，提供行业趋势和发展建议。', '0', 0),
(13, 12, '考研 vs 工作选择', 13, '纠结者', 'kaoyan_vs_job.jpg', '考研or工作.txt', '深入分析应届生在考研和直接工作之间的优劣势，结合真实案例，帮助同学们做出合理选择。', '0', 0),
