INSERT INTO `writer` VALUES (1, '张老师', '1982年7月', '男', '北京', '计算机系讲师，毕业于北京大学，主要研究方向为网络安全与大数据，曾参与多个国家级项目。', 'zhanglaoshi.jpg');
INSERT INTO `writer` VALUES (2, '李华', '1995年5月', '女', '山东青岛', '青岛大学软件工程专业本科生，热爱编程与人工智能，曾获蓝桥杯大赛一等奖。', 'lihua.jpg');
INSERT INTO `writer` VALUES (3, '王伟', '1980年3月', '男', '江苏南京', '网络技术讲师，负责过多个校园技术论坛和讲座，现为校园论坛活动组织者。', 'wangwei.jpg');
INSERT INTO `writer` VALUES (4, '陈老师', '1975年11月', '男', '浙江杭州', '计算机科学与技术系教授，毕业于复旦大学，研究方向为软件工程与数据库管理，曾发表多篇学术论文。', 'chenlaoshi.jpg');
INSERT INTO `writer` VALUES (5, '赵鹏', '1998年1月', '男', '湖北武汉', '计算机专业硕士生，热衷于人工智能领域，已参与多个科研项目，并在国内外学术期刊发表多篇论文。', 'zhaopeng.jpg');
INSERT INTO `writer` VALUES (6, '刘梦', '1994年9月', '女', '山东烟台', '青岛大学计算机科学与技术专业本科生，兴趣包括编程、数学建模等，现为校园论坛管理组成员。', 'liumeng.jpg');
INSERT INTO `writer` VALUES (7, '孙颖', '1992年2月', '女', '陕西西安', '网络安全专业硕士生，研究方向为数据加密和网络防御，参加过多次全国黑客技术比赛。', 'sunying.jpg');
INSERT INTO `writer` VALUES (8, '朱涛', '1987年8月', '男', '上海', '计算机系讲师，研究方向为云计算、大数据存储，参与过多个行业项目。', 'zhutao.jpg');
INSERT INTO `writer` VALUES (9, '张博', '1994年10月', '男', '江西南昌', '软件工程专业本科生，曾获得全国程序设计大赛银奖，参与过多个校园项目的开发。', 'zhangbo.jpg');
INSERT INTO `writer` VALUES (10, '杨扬', '1997年12月', '女', '辽宁沈阳', '电子信息专业硕士生，专注于物联网技术研究，喜欢参加技术交流和学术讨论。', 'yangyang.jpg');
INSERT INTO `writer` VALUES (11, '黄晓', '1985年6月', '男', '广东深圳', '校园论坛技术顾问，网络安全专家，致力于提高校园内网络安全防护和数据保护水平。', 'huangxiao.jpg');
INSERT INTO `writer` VALUES (12, '李婷', '1993年3月', '女', '河北唐山', '计算机系教师，热衷于网络管理和教育技术，已在多家技术公司担任顾问。', 'liting.jpg');
INSERT INTO `writer` VALUES (13, '刘俊杰', '1990年4月', '男', '山西太原', '计算机技术专业博士生，专注于人工智能算法优化与大数据挖掘，曾在国际学术期刊上发表多篇论文。', 'liujunjie.jpg');
INSERT INTO `writer` VALUES (14, '王文娟', '1983年11月', '女', '天津', '校园论坛运营主管，负责论坛内容审核和管理工作，推动校园论坛活动的组织和策划。', 'wangwenjuan.jpg');
INSERT INTO `writer` VALUES (15, '朱小玲', '1991年7月', '女', '重庆', '网络工程硕士生，擅长网络架构设计与云计算技术，参与多个国内外项目的部署与运维工作。', 'zhuxiaoling.jpg');
INSERT INTO `writer` VALUES (16, '周凯', '1989年9月', '男', '北京', '计算机科学与技术系讲师，主讲操作系统、编程语言等课程，参与过多个在线教育平台的建设。', 'zhoukai.jpg');
INSERT INTO `writer` VALUES (17, '陈丽', '1995年5月', '女', '山东济南', '计算机专业硕士生，擅长开发和维护校园网站，曾负责校园论坛的开发和推广。', 'chenli.jpg');
INSERT INTO `writer` VALUES (18, '刘欣', '1996年3月', '男', '黑龙江哈尔滨', '计算机专业博士生，专注于计算机视觉与人工智能的应用，常在校园论坛分享技术讲座。', 'liuxin.jpg');
INSERT INTO `writer` VALUES (19, '张文', '1997年10月', '男', '福建厦门', '智能科技方向本科生，积极参与校园论坛活动，倡导校园科技创新与学生间的技术分享。', 'zhangwen.jpg');
INSERT INTO `writer` VALUES (20, '李雨欣', '1995年8月', '女', '四川成都', '计算机系学生，参与过多个校园科技项目，喜欢分享编程技巧和算法思想，论坛活跃分子。', 'liyuxin.jpg');
INSERT INTO `writer` VALUES (21, '王鹏飞', '1982年12月', '男', '陕西西安', '网络安全与信息技术系教师，研究方向为网络防护与数据隐私保护，致力于提升校园网络的安全性。', 'wangpengfei.jpg');
INSERT INTO `writer` VALUES (22, '孙晓丽', '1994年1月', '女', '浙江温州', '人工智能与机器学习专业硕士生，热衷于学术研究，校园论坛技术专家和活动策划者。', 'sunxiaoli.jpg');
INSERT INTO `writer` VALUES (23, '张建国', '1986年3月', '男', '江西吉安', '计算机网络与云计算讲师，主要教授数据库与信息管理课程，曾指导多个学生项目。', 'zhangjianguo.jpg');
INSERT INTO `writer` VALUES (24, '林小娟', '1990年10月', '女', '江苏南京', '校园论坛管理员，负责论坛活动和讨论版块的建设与维护，致力于提升论坛的用户体验。', 'linxiaojun.jpg');
INSERT INTO `writer` VALUES (25, '黄立东', '1983年2月', '男', '河南郑州', '计算机技术专业讲师，研究领域包括网络技术、信息安全和数据挖掘，参与过校园论坛相关的研究项目。', 'huanglidong.jpg');
INSERT INTO `writer` VALUES (26, '郑楠', '1998年8月', '女', '湖南长沙', '计算机专业本科生，专注于人工智能方向，积极参与校园论坛讨论并分享编程技巧。', 'zhengnan.jpg');
INSERT INTO `writer` VALUES (27, '冯东辉', '1990年5月', '男', '重庆', '软件工程硕士生，研究方向为云计算、大数据，曾多次在校园论坛分享技术讲座。', 'fengdonghui.jpg');
